package cn.shanhai.game;
import java.awt.*;import java.awt.geom.*;import java.awt.image.*;import javax.imageio.*;import java.io.*;import java.util.*;
public class RenderPreview implements Board.Ink {
 BufferedImage img=new BufferedImage(1280,720,BufferedImage.TYPE_INT_RGB);Graphics2D g=img.createGraphics();HashMap<String,BufferedImage> arts=new HashMap<>();Font serif,normal;
 RenderPreview()throws Exception{g.setRenderingHint(RenderingHints.KEY_ANTIALIASING,RenderingHints.VALUE_ANTIALIAS_ON);g.setRenderingHint(RenderingHints.KEY_TEXT_ANTIALIASING,RenderingHints.VALUE_TEXT_ANTIALIAS_ON);serif=Font.createFont(Font.TRUETYPE_FONT,new File("app/src/main/assets/serif.otf"));normal=new Font("Noto Sans CJK SC",0,20);for(String id:new String[]{"qingqiu","yinglong","jingwei","zhuyin","table"})arts.put(id,ImageIO.read(new File("app/src/main/assets/art/"+id+".jpg")));}
 public void poly(float[] pts,int color){Path2D.Float path=new Path2D.Float();path.moveTo(pts[0],pts[1]);for(int i=2;i<pts.length;i+=2)path.lineTo(pts[i],pts[i+1]);path.closePath();g.setColor(new Color(color,true));g.fill(path);}
 public void rect(float x,float y,float w,float h,int c,float r){g.setColor(new Color(c,true));g.fill(new RoundRectangle2D.Float(x,y,w,h,r*2,r*2));}public void line(float x,float y,float x2,float y2,int c,float w){g.setColor(new Color(c,true));g.setStroke(new BasicStroke(w));g.draw(new Line2D.Float(x,y,x2,y2));}public void circle(float x,float y,float r,int c){g.setColor(new Color(c,true));g.fill(new Ellipse2D.Float(x-r,y-r,r*2,r*2));}public void text(String s,float x,float y,float sz,int c,boolean ser){g.setColor(new Color(c,true));g.setFont((ser?serif:normal).deriveFont(sz));g.drawString(s,x,y);}public void art(String id,float x,float y,float w,float h,int alpha){BufferedImage b=arts.get(id);float f=Math.max(w/b.getWidth(),h/b.getHeight());int sw=Math.min(b.getWidth(),(int)(w/f)),sh=Math.min(b.getHeight(),(int)(h/f)),sx=(b.getWidth()-sw)/2;g.setComposite(AlphaComposite.getInstance(AlphaComposite.SRC_OVER,alpha/255f));g.drawImage(b,(int)x,(int)y,(int)(x+w),(int)(y+h),sx,0,sx+sw,sh,null);g.setComposite(AlphaComposite.SrcOver);}
 public static void main(String[] args)throws Exception{Board b=new Board(new Board.Host(){public void sound(String s){}public void save(){}public void settings(){}});new File("build/previews").mkdirs();for(String s:new String[]{"home","choose","battle","rules","settings","response","cards","result"}){RenderPreview r=new RenderPreview();b.game=new Engine(0,12);b.screen=s;b.modal="";if(s.equals("rules")||s.equals("settings")||s.equals("cards")){b.screen="battle";b.modal=s;}if(s.equals("response")){b.screen="battle";b.game.phase=1;b.game.pendingTarget=0;b.game.pendingSource=1;b.game.pendingCard=0;}if(s.equals("result")){b.screen="battle";b.game.phase=3;b.game.winner=0;}b.render(r);ImageIO.write(r.img,"png",new File("build/previews/"+s+".png"));}System.out.println("Rendered 8 screens using shared Board renderer");}
}
